const tabId = 118779795;
const groundInfo = await browserjs(tabId, () => {
  const elements = Array.from(document.querySelectorAll('*'));
  const target = elements.find(el => el.children.length === 0 && el.textContent.trim() === 'FedEx Ground®');
  if (!target) return null;
  // Let's inspect its ancestors until we find the card
  let cur = target;
  let card = null;
  while (cur && cur !== document.body) {
    if (cur.className && typeof cur.className === 'string' && (cur.className.includes('card') || cur.className.includes('row') || cur.className.includes('service') || cur.className.includes('rate'))) {
      card = cur;
      break;
    }
    cur = cur.parentElement;
  }
  return {
    targetTag: target.tagName,
    parentText: target.parentElement?.innerText,
    cardText: card ? card.innerText : cur?.innerText,
    cardHtml: card ? card.outerHTML.slice(0, 500) : null
  };
});

